Hình quạt tô màu đỏ ở hình vẽ bên dưới có bán kính bằng $13$ dm và góc ở tâm bằng $140^{\circ}$. Tính diện tích của hình quạt đó.

\choice
{ $ \dfrac{4735}{72} \pi dm^{2}$   }
   {  $ \dfrac{23503}{360} \pi dm^{2}$ }
     { $ \dfrac{2351}{36} \pi dm^{2}$  }
    { \True $ \dfrac{1183}{18} \pi cm^{2}$ }
}{
\begin{tikzpicture}

    % Vẽ hình quạt đỏ với góc ở tâm là 150 độ và trục tung làm trục đối xứng
    \fill[red] (0,0) -- (4,0) arc[start angle=0, end angle=150, radius=4cm] -- cycle;

    % Vẽ tay cầm ở dưới và đối xứng qua trục tung
    \fill[orange] (0,-0.2) -- (0.5,-0.8) arc[start angle=-60, end angle=-120, radius=0.5cm] -- cycle;

\end{tikzpicture}
}
\loigiai{
\begin{center}
\begin{tikzpicture}[scale=0.72, font=\footnotesize, line cap=round, line join=round]
\coordinate (O) at (0,0);
\coordinate (A) at (140:2.6);
\coordinate (B) at (0:2.6);
\fill[pattern=north east lines, pattern color=blue!55] (O) -- (B) arc (0:140:2.6) -- cycle;
\draw[thick] (O) -- (B) arc (0:140:2.6) -- (O);
\draw[blue!80!black, thick] (0:0.75) arc (0:140:0.75);
\node[fill=white, inner sep=1pt, blue!80!black] at (70.0:1.18) {$140^\circ$};
\node[below] at ($(O)!0.5!(B)$) {$R=13$};
\fill (O) circle (1.5pt) node[below left] {$O$};
\fill (A) circle (1.5pt) node[above] {$A$};
\fill (B) circle (1.5pt) node[below right] {$B$};
\end{tikzpicture}
\end{center}
Diện tích của hình quạt là $S= \dfrac{\pi . 13^{2}. 140}{360}= \dfrac{1183}{18} \pi dm^{2}$
}\end{ex}

\begin{ex}%[9H5H3-0]
\immini[thm]{
Hình quạt tô màu đỏ ở hình vẽ bên dưới có bán kính bằng $10$ dm và góc ở tâm bằng $130^{\circ}$. Tính diện tích của hình quạt đó.

\choice
{ $ \dfrac{4337}{120} \pi dm^{2}$   }
   { $ \dfrac{215}{6} \pi dm^{2}$  }
     { \True $ \dfrac{325}{9} \pi cm^{2}$ }
    {  $ \dfrac{3211}{90} \pi dm^{2}$ }
}{
\begin{tikzpicture}

    % Vẽ hình quạt đỏ với góc ở tâm là 150 độ và trục tung làm trục đối xứng
    \fill[red] (0,0) -- (4,0) arc[start angle=0, end angle=150, radius=4cm] -- cycle;

    % Vẽ tay cầm ở dưới và đối xứng qua trục tung
    \fill[orange] (0,-0.2) -- (0.5,-0.8) arc[start angle=-60, end angle=-120, radius=0.5cm] -- cycle;

\end{tikzpicture}
}
\loigiai{
\begin{center}
\begin{tikzpicture}[scale=0.72, font=\footnotesize, line cap=round, line join=round]
\coordinate (O) at (0,0);
\coordinate (A) at (130:2.6);
\coordinate (B) at (0:2.6);
\fill[pattern=north east lines, pattern color=blue!55] (O) -- (B) arc (0:130:2.6) -- cycle;
\draw[thick] (O) -- (B) arc (0:130:2.6) -- (O);
\draw[blue!80!black, thick] (0:0.75) arc (0:130:0.75);
\node[fill=white, inner sep=1pt, blue!80!black] at (65.0:1.18) {$130^\circ$};
\node[below] at ($(O)!0.5!(B)$) {$R=10$};
\fill (O) circle (1.5pt) node[below left] {$O$};
\fill (A) circle (1.5pt) node[above] {$A$};
\fill (B) circle (1.5pt) node[below right] {$B$};
\end{tikzpicture}
\end{center}
Diện tích của hình quạt là $S= \dfrac{\pi . 10^{2}. 130}{360}= \dfrac{325}{9} \pi dm^{2}$
}\end{ex}
